#!/usr/bin/env python
# cofactor (96, maths, 200pts): bit oracle, NO factoring needed.
# get_bit(i) returns g^k iff bit i of FLAG is 1, else uniform randint(1,N-1).
# N = product of 16 safe primes; phi is GIVEN, so Q = phi>>16 (odd part).
# g^Q has order 2, so for ANY g^k: (g^k)^Q = (g^Q)^k in {1, g^Q} -> ALWAYS passes.
# The Q-power map's image is the 2^6-torsion (2^16 elems); a uniform h (bit 0)
# lands in {1, g^Q} with prob 2^-15 (verified 0/2000 locally).
# (Old Jacobi/QR test was useless: Jacobi(g^k/N)=(-1)^k is 50/50.)
import socket, json, time


g=986762276114520220801525811758560961667498483061127810099097
Q=phi>>16
gQ=pow(g,Q,N)
NB=43*8  # 344 bits (FLAG is 43 bytes)
s=socket.create_connection(("socket.cryptohack.org",13398),timeout=30); s.settimeout(30)
s.recv(65536)
def next_obj():
    buf=b""
    for _ in range(1000):
        b=buf.find(b"{")
        if b>=0:
            try: obj,i=json.JSONDecoder().raw_decode(buf[b:].decode()); return obj
            except json.JSONDecodeError: pass
        d=s.recv(65536)
        if not d: break
        buf+=d
    raise RuntimeError("no obj")
bits=[0]*NB
t0=time.time()
for i in range(NB):
    s.sendall((json.dumps({"option":"get_bit","i":i})+"\n").encode())
    r=next_obj()
    h=int(r["bit"],16)
    t=pow(h,Q,N)
    bits[i]=1 if (t==1 or t==gQ) else 0
    if i%64==0:
        print(f"{i}/{NB}  ({time.time()-t0:.0f}s)",flush=True)
flag=bytes(sum(bits[i*8+b]<<b for b in range(8)) for i in range(43))
print("FLAG:", flag, flush=True)
s.close()
